def load() -> pd.DataFrame:
    import pandas as pd, os
    base = 'data/wildfire/input'
    rows = []
    for fn in sorted(os.listdir(base)):
        p = os.path.join(base, fn)
        if os.path.isfile(p):
            rows.append({'filename': fn, 'lower': fn.lower()})
    return pd.DataFrame(rows)

