def process(weatherEvents) -> pd.DataFrame:
    import pandas as pd
    cols = list(weatherEvents.columns)
    def looks_like_date(col):
        s = col.lower()
        return any(k in s for k in ['date', 'day', 'time', 'timestamp'])

    out = []
    for c in cols:
        lc = c.lower()
        out.append({
            'column': c,
            'lower': lc,
            'dtype': str(weatherEvents[c].dtype),
            'n_null': int(weatherEvents[c].isna().sum()),
            'example1': str(weatherEvents[c].dropna().iloc[0]) if weatherEvents[c].notna().any() else None,
            'is_date_name': looks_like_date(c),
            'is_lat_name': 'lat' in lc,
            'is_lon_name': 'lon' in lc or 'lng' in lc,
            'is_precip_name': any(k in lc for k in ['prcp','precip','ppt','rain'])
        })
    return pd.DataFrame(out).sort_values(['is_precip_name','is_date_name','is_lat_name','is_lon_name'], ascending=False).reset_index(drop=True)

def process(weatherEvents) -> pd.DataFrame:
    import pandas as pd
    # show a focused set of potentially relevant columns if present
    cols = list(weatherEvents.columns)
    key_like = []
    for c in cols:
        lc = c.lower()
        if any(k in lc for k in ['station','stid','id','name','date','day','time','lat','lon','lng','prcp','precip','ppt','rain']):
            key_like.append(c)
    # keep order, unique
    seen = set(); key_like2=[]
    for c in key_like:
        if c not in seen:
            seen.add(c); key_like2.append(c)
    show = key_like2[:25] if key_like2 else cols[:25]
    return weatherEvents[show].head(30)
